(function(root){
 'use strict';
 const G=typeof module!=='undefined'&&module.exports?require('./greenhouse-model.js'):root.NOVAGreenhouse;
 const modes={Normal:{greenhouse:30,habitat:40,emu:20,growth:1,time:240},Reduced:{greenhouse:18,habitat:26,emu:12,growth:.55,time:150},Critical:{greenhouse:8,habitat:12,emu:6,growth:.15,time:75}};
 const fresh=()=>({day:0,modes:{greenhouse:'Normal',habitat:'Normal',emu:'Normal'},outdoor:false,health:100,growth:0,exposure:0,allocation:{greenhouse:0,habitat:0,emu:0},report:null});
 function normalize(raw){const p=fresh();if(!raw)return p;for(const k of Object.keys(p.modes))if(Object.hasOwn(modes,raw.modes?.[k]))p.modes[k]=raw.modes[k];for(const k of ['health','growth','exposure','day'])if(Number.isFinite(raw[k]))p[k]=Math.max(0,Math.min(k==='day'?99999:k==='exposure'?99999:100,raw[k]));p.outdoor=raw.outdoor===true;for(const k of Object.keys(p.allocation))if(Number.isFinite(raw.allocation?.[k]))p.allocation[k]=Math.max(0,Math.min(100,raw.allocation[k]));if(raw.report&&['generation','total','available','remaining','shortfall','spill'].every(k=>Number.isFinite(raw.report[k])))p.report=JSON.parse(JSON.stringify(raw.report));return p;}
 function forecast(s){if(s.survival.day>=2&&s.survival.day<=4||[9,12,13].includes(s.survival.day))return {name:'Dust storm',eu:10};return [{name:'Clear',eu:80},{name:'Normal',eu:60},{name:'Dusty',eu:35},{name:'Normal',eu:60}][(s.survival.day-1)%4];}
 function project(s,choice=s.powerPlan){const weather=forecast(s),generation=s.powerPlan.day===s.survival.day?0:weather.eu*(s.solarClean?1:.7),costs={};for(const k of ['greenhouse','habitat','emu'])costs[k]=k==='emu'&&!choice.outdoor?0:modes[choice.modes[k]][k];const available=s.powerPlan.day===s.survival.day?s.power+Object.values(s.powerPlan.allocation).reduce((a,b)=>a+b,0):Math.min(100,s.power+generation),total=Object.values(costs).reduce((a,b)=>a+b,0);return {weather,generation,costs,total,available,remaining:Math.max(0,available-total),shortfall:Math.max(0,total-available),spill:Math.max(0,s.power+generation-100)};}
 function confirm(s,choice){if(s.death||s.location!=='ship'||s.powerPlan.day===s.survival.day&&s.powerPlan.exposure>0)return false;const p=s.powerPlan;for(const k of Object.keys(p.modes))if(!Object.hasOwn(modes,choice.modes?.[k]))return false;p.modes={...choice.modes};p.outdoor=choice.outdoor===true;const r=project(s),a=p.allocation;let left=p.day===s.survival.day?s.power+Object.values(p.allocation).reduce((a,b)=>a+b,0):r.available;for(const k of ['habitat','emu','greenhouse']){a[k]=Math.min(left,r.costs[k]);left-=a[k];}s.power=left;p.day=s.survival.day;p.exposure=0;p.report=r;if(failed(s))s.death={cause:'power',day:s.survival.day};return true;}
 function settle(s){const p=s.powerPlan;G.settle(s);p.health=s.greenhouse.health;p.growth=s.greenhouse.trays.filter(t=>!t.harvested).reduce((sum,t)=>sum+Math.min(100,t.age/35*100),0)/3;}
 function outdoorLimit(s){const p=s.powerPlan;return !p.outdoor?0:modes[p.modes.emu].time*Math.min(1,p.allocation.emu/modes[p.modes.emu].emu);}
 function failed(s){const p=s.powerPlan;return p.day===s.survival.day&&(p.allocation.habitat<modes.Critical.habitat||s.location==='surface'&&p.exposure>=outdoorLimit(s));}
 const api={modes,fresh,normalize,forecast,project,confirm,settle,outdoorLimit,failed};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.NOVAPower=api;
})(typeof window!=='undefined'?window:globalThis);
